def normalize_tags(raw_tags, option="--tag"):
    """去除首尾空白、按首次出现顺序去重；空标签报错。大小写保留。

    option 仅用于错误信息，指出触发错误的具体选项（--tag 或
    --exclude-tag）。
    """
    tags = []
    seen = set()
    for raw in raw_tags:
        tag = raw.strip()
        if not tag:
            raise CliError(f"标签 {option} 去除首尾空白后不能为空")
        if tag not in seen:
            seen.add(tag)
            tags.append(tag)
    return tags

